TEMPLATE = '''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Robot Dataset Crash Lab</title><style>
:root{font-family:ui-sans-serif,system-ui,sans-serif;background:#101717;color:#e5eeec;--line:#2f4240;--mint:#9be0c2;--red:#f4ad9f}*{box-sizing:border-box}body{margin:0}header,main{max-width:1250px;margin:auto}header{padding:28px 32px;display:flex;justify-content:space-between;border-bottom:1px solid var(--line)}.brand{font-weight:700;font-size:12px;letter-spacing:.16em}nav{display:flex;gap:18px}button{font:inherit;font-size:11px;color:#bfceca;background:transparent;border:1px solid var(--line);border-radius:5px;padding:10px 13px;cursor:pointer}nav button{border:0;padding:0}nav button.active{color:var(--mint)}main{padding:54px 32px}.eyebrow{font-size:10px;letter-spacing:.18em;color:var(--mint)}h1{font-size:clamp(36px,5vw,64px);max-width:900px;line-height:1.08;letter-spacing:-.045em;font-weight:600;margin:20px 0}p.lede{font-size:16px;line-height:1.8;max-width:800px;color:#9dafaa}.metrics{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid var(--line);border-bottom:1px solid var(--line);margin:38px 0;padding:26px 0;gap:20px}.metrics strong{display:block;font-size:34px;font-weight:500}.metrics span{display:block;font-size:12px;color:#96ada5;margin-top:8px}.section-head{display:flex;justify-content:space-between;gap:20px;align-items:center;margin-bottom:22px}h2{font-size:20px;font-weight:500}.filters{display:flex;gap:8px}.filters button.active{background:#284437;color:#b6f5d6;border-color:#527b65}.trial{border:1px solid var(--line);background:#14201e;border-radius:10px;padding:22px;margin:14px 0}.trial.invalid{border-color:#65483d;background:#271f1b}.trial-top{display:flex;justify-content:space-between;gap:25px}.trial h3{margin:0;font-size:14px;font-weight:550}.protocol{font-family:monospace;font-size:10px;color:#91aea0;display:block;margin-bottom:9px}.badge{color:var(--mint);border:1px solid #3d6651;padding:6px 9px;font-size:10px;border-radius:5px;white-space:nowrap;align-self:flex-start}.invalid .badge{color:var(--red);border-color:#745347}.trail{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin:20px 0;color:#94b5a4;font-size:11px}.stop{color:#f1c184;border:1px solid #695b36;padding:6px;border-radius:4px}.counts{display:flex;gap:30px;font-size:11px;color:#90a69c}.counts strong{font-size:18px;color:#e0eeea;margin-right:6px}.invalid .counts strong{color:var(--red)}details{margin-top:18px;font-size:11px;color:#a5b4ac}summary{cursor:pointer}pre{overflow:auto;padding:15px;border:1px solid var(--line);border-radius:5px;font-size:10px;color:#a6cdbb;max-height:350px}.footer{margin-top:30px;padding-top:22px;border-top:1px solid var(--line);font-size:11px;color:#96a79e;line-height:1.8;max-width:950px}#download{margin-top:24px;background:#a0e3c3;color:#10281c;border:0;font-weight:600}a{color:#b4d7c3}.error{font-size:10px;color:var(--red);margin-top:12px}button:focus,summary:focus{outline:2px solid #b1e1c6;outline-offset:4px}@media(max-width:700px){header{padding:23px 20px}main{padding:32px 20px}.section-head{display:block}.filters{flex-wrap:wrap}.metrics{gap:12px}.metrics strong{font-size:27px}.metrics span{font-size:10px}.trial{padding:18px 14px}.trial-top{display:block}.badge{display:inline-block;margin-top:13px}.counts{gap:15px;flex-wrap:wrap}}
</style></head><body><header><span class="brand">ROBOT / DATASET CRASH LAB</span><nav><button data-lang="fr">FR</button><button data-lang="en">EN</button><button data-lang="es">ES</button></nav></header><main><p class="eyebrow" data-i18n="eyebrow"></p><h1 data-i18n="title"></h1><p class="lede" data-i18n="lede"></p><section class="metrics"><div><strong id="safe-count"></strong><span data-i18n="safe"></span></div><div><strong id="kill-count"></strong><span data-i18n="kills"></span></div><div><strong id="broken-count"></strong><span data-i18n="broken"></span></div></section><div class="section-head"><h2 data-i18n="matrix"></h2><div class="filters"><button data-filter="all" data-i18n="all"></button><button data-filter="safe" data-i18n="onlySafe"></button><button data-filter="metadata_first" data-i18n="onlyBroken"></button></div></div><div id="trials"></div><button id="download" data-i18n="download"></button><p class="footer" data-i18n="limit"></p><a href="https://github.com/gbesse/robot-dataset-crash-lab">GitHub ↗</a></main><script>
const report=__REPORT__,translations=__I18N__;let lang=__LANG__,filter='all';const $=id=>document.getElementById(id),el=(tag,text,cls)=>{const x=document.createElement(tag);if(text!==undefined)x.textContent=text;if(cls)x.className=cls;return x;};
function render(){const m=translations[lang];document.documentElement.lang=lang;document.querySelectorAll('[data-i18n]').forEach(x=>x.textContent=m[x.dataset.i18n]);document.querySelectorAll('[data-lang]').forEach(b=>b.classList.toggle('active',b.dataset.lang===lang));document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===filter));const safe=report.trials.filter(t=>t.protocol==='safe'),broken=report.trials.filter(t=>t.protocol==='metadata_first');$('safe-count').textContent=safe.filter(t=>t.snapshot.valid&&t.resumed?.valid).length+'/'+safe.length;$('kill-count').textContent=report.real_process_kills;$('broken-count').textContent=broken.filter(t=>!t.snapshot.valid).length+'/'+broken.length;$('trials').replaceChildren();for(const trial of report.trials.filter(t=>filter==='all'||t.protocol===filter)){const box=el('article',undefined,'trial'+(trial.snapshot.valid?'':' invalid'));const top=el('div',undefined,'trial-top'),heading=el('div');heading.append(el('code',trial.protocol,'protocol'),el('h3',m[trial.checkpoint]));top.append(heading,el('span',trial.snapshot.valid?m.valid:m.invalid,'badge'));box.append(top);const trail=el('div',undefined,'trail');for(const event of trial.events){trail.append(el('span',m[event.checkpoint]),el('span','→'));}trail.append(el('span','SIGKILL · '+trial.returncode,'stop'));box.append(trail);const counts=el('div',undefined,'counts');for(const [n,label]of [[trial.snapshot.visible_episodes,m.episodes],[trial.snapshot.frame_count,m.frames]]){const item=el('span');item.append(el('strong',n),el('span',label));counts.append(item);}counts.append(el('span',trial.resumed?.valid?m.resume:m.refused));box.append(counts);for(const error of trial.snapshot.errors)box.append(el('div',m.error+' · '+error.code,'error'));const details=el('details');details.append(el('summary',m.details),el('pre',JSON.stringify(trial,null,2)));box.append(details);$('trials').append(box);}}
document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>{lang=b.dataset.lang;render();}));document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;render();}));$('download').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'})),a=el('a');a.href=url;a.download='robot-crash-matrix.json';a.click();URL.revokeObjectURL(url);});render();
</script></body></html>'''


def html_report(report, lang="en"):
    if lang not in I18N:
        raise ValueError("invalid_language")
    encode = lambda x: json.dumps(x, ensure_ascii=False, allow_nan=False).replace("<", "\\u003c")
    return TEMPLATE.replace("__REPORT__", encode(report)).replace("__I18N__", encode(I18N)).replace("__LANG__", encode(lang))
